"""H4: the difference between two policy versions as plain sentences, generated by code (never the LLM).

Built on engine.policy_diff: every changed path produces a sentence. Limits, windows, rules, overrides,
derived facts, line checks and flags get readable sentences; anything not recognised falls back to
"path: old -> new", so a change can never go unmentioned.
"""
import json
from decimal import Decimal

from engine.policy_diff import diff

LABELS = {  # fact paths in words; anything else is shown as its path
    "requirement.value_inr": "requirement value", "requirement.plant": "plant", "plant.plant": "plant",
    "first_line.plant": "plant", "line.plant": "plant", "item.category": "item category",
    "item.item_type": "item type", "item.item_code": "item code", "requirement.item_code": "item code",
    "derived.is_emergency": "it is an emergency", "history.bought_from_active": "bought from an Active supplier recently",
    "contract.usable": "a contract can be used", "requirement.is_new_item": "it is a new item",
    "requirement.lead_time_days": "lead time in days", "requirement.total_quantity": "total quantity",
    "requirement.valuation_source": "valuation source", "requirement.valuation_price": "valuation price",
    "line.quantity": "quantity", "line.need_by_date": "need-by date", "line.created_at": "creation time",
    "first_line.need_by_date": "need-by date", "requirement.date": "requirement date",
    "item.standard_price": "standard price", "requirement.line_count": "number of lines",
    "history.po_count": "POs in the purchase window", "history.days_since_last_po": "days since the last PO",
    "preferred.list_size": "preferred suppliers", "first_line.urgency": "urgency", "line.urgency": "urgency",
}
LIMIT_NAMES = {"emergency_po": "Emergency PO", "spot_po": "Spot PO", "rfq": "RFQ"}


def limit_name(key):
    return LIMIT_NAMES.get(key, key.replace("_", " "))
COMPARE = {"<": "below", "<=": "at or below", ">": "above", ">=": "at or above"}
SUPPLIER = {"contract_supplier": "the contract supplier", "preferred_rank_1": "the 1st preferred supplier",
            "suggest": "suggested suppliers", "none": "no supplier"}
PRICE = {"contract_rate": "at the contract rate", "reference_price": "at its reference price", "none": ""}


def inr(value):
    """Indian digit grouping: 1500000 -> 15,00,000 (decimals kept)."""
    d = Decimal(str(value))
    sign, text = ("-" if d < 0 else ""), format(abs(d).normalize(), "f")
    whole, _, frac = text.partition(".")
    if len(whole) > 3:
        head, tail = whole[:-3], whole[-3:]
        groups = []
        while len(head) > 2:
            groups.insert(0, head[-2:])
            head = head[:-2]
        whole = ",".join(([head] if head else []) + groups + [tail])
    return sign + whole + ("." + frac if frac else "")


def label(path):
    if path in LABELS:
        return LABELS[path]
    if path.startswith("derived."):
        return path[len("derived."):].replace("_", " ")
    return path


def literal(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float, Decimal)):
        return inr(value)
    if value is None:
        return "nothing"
    return f"'{value}'" if isinstance(value, str) else json.dumps(value)


def limit_words(limit):
    return f"{COMPARE.get(limit.get('operator'), limit.get('operator'))} {inr(limit.get('value'))}" if isinstance(limit, dict) else str(limit)


def words(expr, params=None):
    """A JSON Logic expression in plain words."""
    params = params or {}
    if not isinstance(expr, dict):
        return literal(expr)
    (op, args), = expr.items()
    args = args if isinstance(args, list) else [args]
    w = lambda e: words(e, params)  # noqa: E731
    if op == "var":
        return label(args[0])
    if op in ("==", "===", "!=", "!=="):
        a, b = args
        negate = op.startswith("!")
        if isinstance(b, bool):
            return ("not " if b == negate else "") + w(a)
        return f"{w(a)} is {'not ' if negate else ''}{w(b)}"
    if op in COMPARE:
        return f"{w(args[0])} is {COMPARE[op]} {w(args[1])}"
    if op == "meets_limit":
        name = args[1]
        limit = params.get("limits", {}).get(name.split(".", 1)[-1], {})
        return f"{w(args[0])} is {limit_words(limit)} ({limit_name(name.split('.', 1)[-1])} limit)" if limit else f"{w(args[0])} meets {name}"
    if op in ("and", "or"):
        parts = [f"({w(a)})" if isinstance(a, dict) and next(iter(a)) in ("and", "or") else w(a) for a in args]
        return f" {op} ".join(parts)
    if op == "!":
        return f"not ({w(args[0])})"
    if op == "!!":
        return f"{w(args[0])} is set"
    if op == "in":
        return f"{w(args[0])} is one of {', '.join(literal(x) for x in args[1])}" if isinstance(args[1], list) else f"{w(args[0])} is in {w(args[1])}"
    if op in ("some", "all", "none"):
        return {"some": "any line has ", "all": "every line has ", "none": "no line has "}[op] + w(args[1])
    if op == "date_diff_days":
        return f"days from {w(args[1])} to {w(args[0])}"
    if op in ("+", "-", "*", "/"):
        nested = lambda a: f"({w(a)})" if isinstance(a, dict) and next(iter(a)) in ("+", "-", "*", "/") else w(a)  # noqa: E731
        return f" {op} ".join(nested(a) for a in args)
    return json.dumps(expr)


def outcome_words(then):
    supplier = SUPPLIER.get(then.get("supplier"), then.get("supplier"))
    if then.get("decision") == "PO":
        return f"{then.get('route')} to {supplier} {PRICE.get(then.get('price'), '')}".strip()
    count = then.get("suggest_count", 0)
    return f"{then.get('route')}" + (f" with {count} suggested suppliers" if count else "")


def _window(w):
    if not isinstance(w, dict):
        return str(w)
    unit = {"calendar_days": "calendar days", "hours": "hours", "minutes": "minutes"}.get(w.get("unit"), w.get("unit"))
    return f"{inr(w.get('length'))} {unit}{'' if w.get('inclusive', True) else ' (exclusive)'}"


def _get(doc, path):
    for part in path.split("."):
        doc = doc.get(part) if isinstance(doc, dict) else None
    return doc


def _entity(path):
    """'rules[5.3A].when' -> ('rules', '5.3A', 'when')."""
    head, _, rest = path.partition("]")
    section, _, key = head.partition("[")
    return section, key, rest.lstrip(".")


def explain(old, new):
    """Plain sentences for every difference from old to new."""
    changes = diff(old, new)
    p_old, p_new = old.get("parameters", {}), new.get("parameters", {})
    sentences, done = [], set()
    for kind, path, before, after in changes:
        if path in done:
            continue
        if path in ("version", "effective_from", "supersedes", "source_document", "change_summary", "policy_id"):
            name = {"effective_from": "Effective from", "supersedes": "Supersedes", "source_document": "Source document",
                    "change_summary": "Change summary", "version": "Version", "policy_id": "Policy id"}[path]
            sentences.append(f"{name}: {literal(before) if before is not None else 'none'} becomes {literal(after)}")
            continue
        if path == "rule order":
            continue  # described with the rules that moved or were added, below
        if path.startswith("parameters."):
            parts = path.split(".")
            if parts[1] == "limits" and len(parts) >= 4:
                key = ".".join(parts[:3])
                done |= {p for _, p, _, _ in changes if p.startswith(key + ".")}
                a, b = _get(p_old, ".".join(parts[1:3])), _get(p_new, ".".join(parts[1:3]))
                name = limit_name(parts[2])
                if a is None:
                    sentences.append(f"New limit {name}: {limit_words(b)}")
                elif b is None:
                    sentences.append(f"{name} limit removed (was {limit_words(a)})")
                else:
                    sentences.append(f"{name} limit: {limit_words(a)} becomes {limit_words(b)}")
                continue
            parent = ".".join(parts[1:-1])
            a, b = _get(p_old, parent), _get(p_new, parent)
            if isinstance(b, dict) and "length" in b and parts[-1] in ("length", "unit", "inclusive"):
                done |= {f"parameters.{parent}.{k}" for k in ("length", "unit", "inclusive")}
                title = parent.replace(".", " ").replace("_", " ")
                sentences.append(f"{title[0].upper() + title[1:]}: {_window(a)} becomes {_window(b)}")
                continue
            title = ".".join(parts[1:])
            if kind == "~":
                sentences.append(f"Setting {title}: {literal(before)} becomes {literal(after)}")
            elif kind == "+":
                sentences.append(f"New setting {title}: {literal(after)}")
            else:
                sentences.append(f"Setting {title} removed (was {literal(before)})")
            continue
        section, key, field = _entity(path)
        if section in ("rules", "overrides", "derived_facts", "line_checks", "line_flags"):
            done |= {p for _, p, _, _ in changes if _entity(p)[:2] == (section, key)}
            sentences.append(_entity_sentence(section, key, old, new, p_new))
            continue
        sentences.append(f"{path}: {literal(before)} becomes {literal(after)}")
    sentences += _order_sentences(old, new)
    return sentences


def _find(doc, section, key):
    id_key = "name" if section == "derived_facts" else "id"
    return next((e for e in doc.get(section) or [] if e.get(id_key) == key), None)


def _entity_sentence(section, key, old, new, params):
    a, b = _find(old, section, key), _find(new, section, key)
    noun = {"rules": "rule", "overrides": "override", "derived_facts": "derived fact", "line_checks": "line check",
            "line_flags": "line flag"}[section]
    if b is None:
        return f"{noun[0].upper() + noun[1:]} {key} removed"
    if section == "rules":
        ids = [r.get("id") for r in new.get("rules", [])]
        pos = ids.index(key)
        where = f"after {ids[pos - 1]}" if pos else "first"
        text = f"applies when {words(b.get('when'), params)}; outcome: {outcome_words(b.get('then', {}))}"
        if a is None:
            return f"New rule {key} '{b.get('title', '')}' {where}: {text}"
        what = [f for f in ("when", "then", "title", "clause_text") if a.get(f) != b.get(f)]
        if what == ["clause_text"]:
            return f"Rule {key} '{b.get('title', '')}': wording updated to '{b.get('clause_text')}' (condition and outcome unchanged)"
        return f"Rule {key} '{b.get('title', '')}' changed ({', '.join(what)}): now {text}"
    if section == "overrides":
        change = ", ".join(f"{k} {literal(v)}" for k, v in (b.get("set") or {}).items())
        verb = "New override" if a is None else "Override changed:"
        return f"{verb} {key}: {b.get('parameter')} gets {change} when {words(b.get('when'))}"
    if section == "derived_facts":
        verb = "New derived fact" if a is None else "Derived fact changed:"
        return f"{verb} {key} = {words(b.get('expr'))}"
    text = b.get("reason") if section == "line_checks" else b.get("message")
    verb = f"New {noun}" if a is None else f"{noun[0].upper() + noun[1:]} changed:"
    return f"{verb} {key} '{b.get('title', '')}': when {words(b.get('when'))}, {text}"


def _order_sentences(old, new):
    before = [r.get("id") for r in old.get("rules", [])]
    after = [r.get("id") for r in new.get("rules", [])]
    kept_before = [r for r in before if r in after]
    kept_after = [r for r in after if r in before]
    return [f"Rule order of existing rules changed: {', '.join(kept_before)} becomes {', '.join(kept_after)}"] \
        if kept_before != kept_after else []
